//! The formatter invocation the gates and `cargo dev fmt` share, and the files it names explicitly.

use std::ffi::OsString;
use std::path::{Path, PathBuf};

use crate::step::Step;

/// The build-script module that the command registry is generated by.
const DISCOVER: &str = "crates/core/build/discover.rs";

/// The build-script module that the topic map is generated by.
const TOPICS: &str = "crates/core/build/topics.rs";

/// The directory whose files are commands.
const COMMANDS_DIR: &str = "crates/core/src/commands";

/// The files `cargo fmt` does not reach by following `mod` declarations, as paths under `repository_root`,
/// sorted: the two build-script modules, discovery and topics, and every `.rs` file below the commands directory.
/// Without a commands directory the list is the two modules alone.
pub fn format_files(repository_root: &Path) -> Vec<PathBuf> {
    let mut files = vec![repository_root.join(DISCOVER), repository_root.join(TOPICS)];
    collect_rust_files(&repository_root.join(COMMANDS_DIR), &mut files);
    files.sort();
    files
}

fn collect_rust_files(directory: &Path, files: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(directory) else {
        return;
    };
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        match entry.file_type() {
            Ok(kind) if kind.is_dir() => collect_rust_files(&path, files),
            Ok(kind) if kind.is_file() && path.extension().is_some_and(|ext| ext == "rs") => {
                files.push(path);
            }
            _ => {}
        }
    }
}

/// The format step: in check mode it reports unformatted files and changes none, otherwise it rewrites them.
pub(crate) fn step(cargo: &Path, repository_root: &Path, check: bool) -> Step {
    let mut args: Vec<OsString> = vec!["fmt".into(), "--all".into()];
    if check {
        args.push("--check".into());
    }
    args.push("--".into());
    args.extend(
        format_files(repository_root)
            .into_iter()
            .map(PathBuf::into_os_string),
    );
    Step {
        name: "fmt",
        program: cargo.to_path_buf(),
        args,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::scratch::Scratch;

    #[test]
    fn the_list_is_the_two_build_modules_and_every_rust_file_under_commands_sorted() {
        let scratch = Scratch::new("format-files");
        let root = scratch.path();
        let commands = root.join(COMMANDS_DIR);
        std::fs::create_dir_all(commands.join("ws")).unwrap();
        std::fs::create_dir_all(commands.join("repo")).unwrap();
        for file in ["ws/index.rs", "ws/add.rs", "repo/list.rs", "version.rs"] {
            std::fs::write(commands.join(file), "").unwrap();
        }
        std::fs::write(commands.join("ws/notes.txt"), "").unwrap();

        assert_eq!(
            format_files(root),
            [
                root.join("crates/core/build/discover.rs"),
                root.join("crates/core/build/topics.rs"),
                root.join("crates/core/src/commands/repo/list.rs"),
                root.join("crates/core/src/commands/version.rs"),
                root.join("crates/core/src/commands/ws/add.rs"),
                root.join("crates/core/src/commands/ws/index.rs"),
            ]
        );
    }

    #[test]
    fn the_list_is_the_two_build_modules_alone_without_a_commands_directory() {
        let scratch = Scratch::new("format-files-absent");
        let root = scratch.path();

        assert_eq!(
            format_files(root),
            [
                root.join("crates/core/build/discover.rs"),
                root.join("crates/core/build/topics.rs"),
            ]
        );
    }

    #[test]
    fn check_mode_alone_carries_the_check_flag() {
        let cargo = Path::new("/toolchain/bin/cargo");
        let root = Path::new("/repository");
        let discover = "/repository/crates/core/build/discover.rs";
        let topics = "/repository/crates/core/build/topics.rs";

        assert_eq!(
            step(cargo, root, true).args,
            ["fmt", "--all", "--check", "--", discover, topics]
        );
        assert_eq!(
            step(cargo, root, false).args,
            ["fmt", "--all", "--", discover, topics]
        );
        assert_eq!(step(cargo, root, false).program, cargo);
    }
}
